    public void test_manyKeys() throws Exception {
      initTestNodes();
      runWithinCommand(() -> {
        ViewModel vm = ViewModels.named("test.com.jetbrains.mpsext.viewmodel.lang.viewmodels.Results").forProject(myProject);
        vm.clear();
        SNode item = getAnnotatedNode("a");
        int count = 500;
        // composite keys [item, "key<i>"], all in the nested map of the item
        for (int i = 0; i < count; i++) {
          List<ViewModelKey> path = ViewModels.path(item);
          ListSequence.fromList(path).addElement(ViewModelKey.forString("key" + i));
          vm.writePath(path, i, null);
        }
        for (int i = 0; i < count; i += 2) {
          List<ViewModelKey> path = ViewModels.path(item);
          ListSequence.fromList(path).addElement(ViewModelKey.forString("key" + i));
          vm.writePath(path, null, null);
        }
        for (int i = 0; i < count; i++) {
          List<ViewModelKey> path = ViewModels.path(item);
          ListSequence.fromList(path).addElement(ViewModelKey.forString("key" + i));
          if (i % 2 == 0) {
            Assert.assertNull(vm.getPath(path));
          } else {
            Assert.assertEquals(Integer.valueOf(i), vm.getPath(path));
          }
        }
        vm.remove(item);
        List<ViewModelKey> last = ViewModels.path(item);
        ListSequence.fromList(last).addElement(ViewModelKey.forString("key" + (count - 1)));
        Assert.assertNull(vm.getPath(last));
      });
    }
